window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-cf04d5d2be27c47c"]={"versions": [{"id": "FIG-cf04d5d2be27c47c", "releases": ["R1.5.1", "R18-10_R4.4.0_R1.5.0", "R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Prüffunktion <code>E2E_P04Check</code> innerhalb der AUTOSAR E2E-Protokoll-Spezifikation (Profile 4). Es spezifiziert die algorithmische Gesamtabfolge auf Empfängerseite zur Integritäts- und Konsistenzprüfung empfangener Daten im Rahmen des AUTOSAR E2E-Schutzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Funktion</strong>: <code>E2E_P04Check</code> mit den Parametern:</li>\n<li><code>Config</code>: Konfigurationsstruktur des E2E-Profils 4.</li>\n<li><code>State</code>: Zustandsstruktur des E2E-Profils 4.</li>\n<li><code>Data</code>: Zeiger auf das zu prüfende Datenarray.</li>\n<li><code>Length</code>: Länge der Nutzdaten.</li>\n<li><strong>Teilaktivitäten (Sub-Aktivitäten mit Aufruf-Symbol)</strong>:</li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li><strong>Entscheidungsknoten / Guards</strong>:</li>\n<li><code>[null input]</code>, <code>[wrong input]</code>, <code>[input ok]</code></li>\n<li><code>NewDataAvailable == TRUE</code> mit Guards <code>[TRUE]</code>, <code>[FALSE]</code></li>\n<li><strong>Rückgabewerte / Endknoten</strong>:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code></li>\n<li><code>return E2E_E_INPUTERR_WRONG</code></li>\n<li><code>return E2E_E_OK</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Initialknoten über den Funktionsaufruf <code>E2E_P04Check(Config, State, Data, Length)</code>.</li>\n<li>Ausführung der Teilaktivität <code>Verify inputs of the check function</code>.</li>\n<li>Verzweigung anhand der Eingangsparameter-Gültigkeit:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[null input]</code>: Verzweigung zum linken Endknoten mit Rückgabe von <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei <code>[wrong input]</code>: Verzweigung zum rechten Endknoten mit Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.</li>\n<li>Bei <code>[input ok]</code>: Übergang zur Verzweigung <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Prüfung der Verfügbarkeit neuer Daten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Pfad <code>[TRUE]</code>: Sequenzielle Abarbeitung der Schritte:</li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li>Weiterleitung zu <code>Do checks</code>.</li>\n<li>Pfad <code>[FALSE]</code>: Umgehung der Extraktions- und Berechnungsschritte direkt zur Aktivität <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Ausführung von <code>Do checks</code> zur Statusbewertung.</li>\n<li>Abschluss am mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation des Ablauf- und Fehlerbehandlungsverhaltens von <code>E2E_P04Check</code> gemäß Requirement <code>[PRS_E2E_00355]</code>. Die Teilaktivitäten sind als modulare Unterschritte definiert, die in nachfolgenden Detaildiagrammen der Spezifikation präzisiert werden. Ungültige Parameter müssen zwingend vor jeglicher Datenextraktion abgefangen und mit den jeweiligen spezifischen Fehlercodes quittiert werden. Das Überspringen der Extraktions- und CRC-Schritte bei Ausbleiben neuer Daten (<code>NewDataAvailable == FALSE</code>) stellt sicher, dass dennoch die Zustandsprüfung (<code>Do checks</code>) zur Erkennung von Timeouts bzw. Kommunikationsausfällen durchlaufen wird.</p>"}, {"id": "FIG-873f8cf36de435bd", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Darstellung des Kontrollflusses der Prüffunktion <code>E2E_P04Check</code> innerhalb der AUTOSAR E2E-Protokoll-Spezifikation (Profile 4). Es spezifiziert die algorithmische Gesamtabfolge auf Empfängerseite zur Integritäts- und Konsistenzprüfung empfangener Daten im Rahmen des AUTOSAR E2E-Schutzes.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Aktivität / Funktion</strong>: <code>E2E_P04Check</code> mit den Parametern:</li>\n<li><code>Config</code>: Konfigurationsstruktur des E2E-Profils 4.</li>\n<li><code>State</code>: Zustandsstruktur des E2E-Profils 4.</li>\n<li><code>Data</code>: Zeiger auf das zu prüfende Datenarray.</li>\n<li><code>Length</code>: Länge der Nutzdaten.</li>\n<li><strong>Teilaktivitäten (Sub-Aktivitäten mit Aufruf-Symbol)</strong>:</li>\n<li><code>Verify inputs of the check function</code></li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li><code>Do checks</code></li>\n<li><strong>Entscheidungsknoten / Guards</strong>:</li>\n<li><code>[null input]</code>, <code>[wrong input]</code>, <code>[input ok]</code></li>\n<li><code>NewDataAvailable == TRUE</code> mit Guards <code>[TRUE]</code>, <code>[FALSE]</code></li>\n<li><strong>Rückgabewerte / Endknoten</strong>:</li>\n<li><code>return E2E_E_INPUTERR_NULL</code></li>\n<li><code>return E2E_E_INPUTERR_WRONG</code></li>\n<li><code>return E2E_E_OK</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Beginn am Initialknoten über den Funktionsaufruf <code>E2E_P04Check(Config, State, Data, Length)</code>.</li>\n<li>Ausführung der Teilaktivität <code>Verify inputs of the check function</code>.</li>\n<li>Verzweigung anhand der Eingangsparameter-Gültigkeit:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Bei <code>[null input]</code>: Verzweigung zum linken Endknoten mit Rückgabe von <code>E2E_E_INPUTERR_NULL</code>.</li>\n<li>Bei <code>[wrong input]</code>: Verzweigung zum rechten Endknoten mit Rückgabe von <code>E2E_E_INPUTERR_WRONG</code>.</li>\n<li>Bei <code>[input ok]</code>: Übergang zur Verzweigung <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Prüfung der Verfügbarkeit neuer Daten:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Pfad <code>[TRUE]</code>: Sequenzielle Abarbeitung der Schritte:</li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li>Weiterleitung zu <code>Do checks</code>.</li>\n<li>Pfad <code>[FALSE]</code>: Umgehung der Extraktions- und Berechnungsschritte direkt zur Aktivität <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li>Ausführung von <code>Do checks</code> zur Statusbewertung.</li>\n<li>Abschluss am mittleren Endknoten mit <code>return E2E_E_OK</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ verbindliche Spezifikation des Ablauf- und Fehlerbehandlungsverhaltens von <code>E2E_P04Check</code> gemäß Requirement <code>[PRS_E2E_00355]</code>. Die Teilaktivitäten sind als modulare Unterschritte definiert, die in nachfolgenden Detaildiagrammen der Spezifikation präzisiert werden. Ungültige Parameter müssen zwingend vor jeglicher Datenextraktion abgefangen und mit den jeweiligen spezifischen Fehlercodes quittiert werden. Das Überspringen der Extraktions- und CRC-Schritte bei Ausbleiben neuer Daten (<code>NewDataAvailable == FALSE</code>) stellt sicher, dass dennoch die Zustandsprüfung (<code>Do checks</code>) zur Erkennung von Timeouts bzw. Kommunikationsausfällen durchlaufen wird.</p>"}, {"id": "FIG-75f701beb0f29693", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Kontrollflusses der Prüffunktion <code>E2E_P44Check</code> innerhalb des AUTOSAR E2E-Protokolls (Profil 44 / PRS_E2EProtocol). Es modelliert die empfängerseitige Verifikationslogik für geschützte Datenstrukturen auf Ebene der E2E-Bibliothek bzw. des E2E-Transformers.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Eingangsschnittstelle</strong>: Funktionsaufruf <code>E2E_P44Check(Config, State, Data, Length)</code>.</li>\n<li><strong>Parameter</strong>:</li>\n<li><code>Config</code>: Konfigurationsstruktur des E2E-Profils 44 (z. B. Offsets, Limits, Data ID).</li>\n<li><code>State</code>: Zustandsspeicher der Prüffunktion (enthält u. a. <code>NewDataAvailable</code>, Counter-Historie, Status).</li>\n<li><code>Data</code>: Zeiger auf den zu prüfenden Nutzdaten- bzw. Serialisierungspuffer.</li>\n<li><code>Length</code>: Länge des Puffers / der Nutzdaten.</li>\n<li><strong>Aktivitäten / Sub-Aktivitäten</strong>:</li>\n<li><code>Verify inputs of the check function</code>: Validierung von Eingangszeigern und Wertegrenzen.</li>\n<li><code>Compute offset</code>: Ermittlung relevanter Feld- und Header-Offsets.</li>\n<li><code>Read Length</code>: Auslesen der übertragenen Längeninformation.</li>\n<li><code>Read Counter</code>: Auslesen des Sequenzzählers aus dem Datenstrom.</li>\n<li><code>Read DataID</code>: Auslesen bzw. Abgleich der Datenkennung.</li>\n<li><code>Read CRC</code>: Auslesen der übertragenen Prüfsumme.</li>\n<li><code>Compute CRC</code>: Neuberechnung der Prüfsumme über die empfangenen Nutzdaten.</li>\n<li><code>Do checks</code>: Durchführung der Status- und Plausibilitätsprüfungen (CRC-Vergleich, Counter-Differenz etc.).</li>\n<li><strong>Verzweigungselement</strong>: Decision Node <code>NewDataAvailable == TRUE</code>.</li>\n<li><strong>Ablauf- und Endknoten</strong>: Initialer Startknoten am Funktionskopf sowie drei <code>return</code>-Aktivitätsendknoten.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li><strong>Initialisierung</strong>: Der Ablauf beginnt mit dem Aufruf von <code>E2E_P44Check(Config, State, Data, Length)</code>.</li>\n<li><strong>Eingangsprüfung</strong>: Die Aktivität <code>Verify inputs of the check function</code> validiert die übergebenen Parameter.</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Tritt ein Null-Zeiger auf (<code>[null input]</code>), verzweigt der Kontrollfluss direkt zum linken <code>return</code>-Endknoten.</li>\n<li>Liegen ungültige Werte vor (<code>[wrong input]</code>), verzweigt der Kontrollfluss direkt zum rechten <code>return</code>-Endknoten.</li>\n<li>Sind die Parameter valide (<code>[input ok]</code>), geht der Kontrollfluss weiter zur Entscheidung <code>NewDataAvailable == TRUE</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Auswertung Datenverfügbarkeit</strong>:</li>\n</ol>\n<ul class=\"fig-list\">\n<li>Wenn <code>[FALSE]</code>, werden Offset-, Lese- und CRC-Berechnungsschritte übersprungen und es wird direkt zu <code>Do checks</code> verzweigt.</li>\n<li>Wenn <code>[TRUE]</code>, wird die sequentielle Auswertung der Nachricht durchlaufen:</li>\n<li><code>Compute offset</code></li>\n<li><code>Read Length</code></li>\n<li><code>Read Counter</code></li>\n<li><code>Read DataID</code></li>\n<li><code>Read CRC</code></li>\n<li><code>Compute CRC</code></li>\n<li>Anschließend Weiterleitung zu <code>Do checks</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Abschlussprüfung & Terminierung</strong>: In <code>Do checks</code> werden die Prüfsummen und Counter bewertet; der Ablauf endet am mittleren <code>return</code>-Endknoten.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li>Die Implementierung der Funktion <code>E2E_P44Check</code> muss deterministisch und seiteneffektarm erfolgen; vor jedem Speicherzugriff ist eine strenge Null-Pointer- und Wertebereichsprüfung obligatorisch.</li>\n<li>Wenn keine neuen Daten empfangen wurden (<code>NewDataAvailable == FALSE</code>), darf kein Deserialisieren oder CRC-Rechnen auf <code>Data</code> stattfinden; der Zustand wird ausschließlich über <code>Do checks</code> fortgeschrieben (z. B. Erkennung von Timeouts / Kommunikationsausfällen).</li>\n<li>Alle Teilaktivitäten mit Rake-Symbol (<code>oo</code>) verweisen auf hierarchisch verfeinerte Unteraktivitäten der Profil-44-Spezifikation und müssen exakt den in AUTOSAR definierten Bit- und Bytereihenfolgen entsprechen.</li>\n</ul>"}], "trans": [{"from": "FIG-cf04d5d2be27c47c", "to": "FIG-873f8cf36de435bd", "fr": "R19-03", "tr": "R19-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li>Beschriftungen / Textumbruch: Der Übergang von <code>E2E_P04Check(Config, State, Data, Length)</code> sowie die Guards <code>[null input]</code>, <code>[input ok]</code>, <code>[wrong input]</code> und die Bedingung <code>NewDataAvailable == TRUE</code> sind mehrzeilig bzw. schmaler umbrochen.</li>\n<li>Bildbeschnitt am unteren Rand: Die Return-Werte an den drei Endknoten (<code>return E2E_E_INPUTERR_NULL</code>, <code>return E2E_E_OK</code>, <code>return E2E_E_INPUTERR_WRONG</code>) sind in FIG-873f8cf36de435bd am unteren Rand stärker abgeschnitten (nur noch Fragmente wie <code>return</code> sichtbar).</li>\n</ul>"}]};
